const express = require('express');
const { QdrantClient } = require('@qdrant/js-client-rest');
const { OpenAIEmbeddings } = require('@langchain/openai');
const db = require('../db');

const app = express();
app.use(express.json());
const qdrant = new QdrantClient({ url: process.env.QDRANT_URL });
const embeddings = new OpenAIEmbeddings();

app.post('/api/knowledge-base/search', async (req, res) => {
  const { workspaceId, query } = req.body;
  if (!workspaceId || !query) {
    return res.status(400).json({ error: 'Missing workspaceId or query' });
  }

  // Verify that authenticated user belongs to the requested workspace
  const member = await db('workspace_users')
    .where({ workspace_id: workspaceId, user_id: req.user.id })
    .first();

  if (!member) {
    return res.status(403).json({ error: 'Access denied to specified workspace' });
  }

  const queryVector = await embeddings.embedQuery(query);
  const searchResults = await qdrant.search('workspace_documents', {
    vector: queryVector,
    limit: 5,
    filter: {
      must: [
        { key: 'workspace_id', match: { value: workspaceId } }
      ]
    }
  });

  return res.json({ hits: searchResults.map(hit => hit.payload) });
});

module.exports = app;
